async function wait(fn,label,timeout=waitBudget){let active=0,previous=Date.now(),last;const deadline=previous+timeout+180000;while(active<timeout&&Date.now()<deadline){const now=Date.now();let visible=true;if(session)try{visible=await js("return document.visibilityState==='visible'");if(!visible){const handle=await call('GET','/window');await call('POST','/window',{handle});visible=await js("return document.visibilityState==='visible'");}}catch(e){last=e;}if(visible)active+=now-previous;previous=now;if(visible)try{const value=await fn();if(value)return value;}catch(e){last=e;}await new Promise(r=>setTimeout(r,150));}throw Error('Timed out: '+label+(last?' · '+last.message:''));}
const exists=selector=>js('return !!document.querySelector(arguments[0])',selector);
const element=selector=>call('POST','/element',{using:'css selector',value:selector});
