 const l=spatialLayout(E.mallOf(s),0,E.STORES),point=person?personStop(l.locals.find(n=>n.id===person),l.spawn,l.nav):l.rects.find(r=>r.id==='ross').door;s.mapPosition={...point,mallId:'orange',floor:0};
 if(variant&&person){const a=E.COMPANION_ACTIVITIES.find(a=>a.person===person);s.companionMemories=[{person,activity:a.id,day:6,mallId:'orange',answers:a.steps.map(step=>step.options[0].id)}];}
